UPDATE recipes SET data = '{"id":"mexican-chicken-corn-salad","category":"lunch","baseServings":4,"tags":["kyckling"],"title":"Mexikansk kyckling- och majssallad","source":"@amateurprochef","sourceUrl":"","badges":["4 portioner","475 kcal/port","58g protein/port","hög protein","snabb","30 min"],"macros":{"kcal":1746,"prot":227,"carb":97,"fat":50},"groups":[{"name":"kyckling","ingredients":[{"name":"kycklingbröst","amount":800,"unit":"g"},{"name":"limejuice","amount":2,"unit":"msk"},{"name":"avokadoolja","amount":1,"unit":"msk"},{"name":"chilipulver","amount":2,"unit":"tsk"},{"name":"spiskummin","amount":1.5,"unit":"tsk"},{"name":"vitlökspulver","amount":1,"unit":"tsk"},{"name":"paprika","amount":1,"unit":"tsk"},{"name":"salt","amount":1,"unit":"tsk"},{"name":"svartpeppar","amount":0.5,"unit":"tsk"}]},{"name":"grönsaker","ingredients":[{"name":"cotijaost","amount":50,"unit":"g"},{"name":"rödlök","amount":1,"unit":"st"},{"name":"röd paprika","amount":1,"unit":"st"},{"name":"koriander","amount":1,"unit":"näve"},{"name":"jalapeños","amount":3,"unit":"st"},{"name":"konserverad majs","amount":330,"unit":"g"}]},{"name":"sås","ingredients":[{"name":"naturell grekisk yoghurt 0%","amount":240,"unit":"g"},{"name":"limejuice","amount":0.5,"unit":"st"},{"name":"chilisås","amount":1,"unit":"msk"},{"name":"tajín","amount":1,"unit":"msk"},{"name":"vatten","amount":120,"unit":"g"},{"name":"salt","amount":1,"unit":"pinch"},{"name":"svartpeppar","amount":1,"unit":"pinch"}]}],"steps":[{"title":"Marinera kyckling","text":"Skär kycklingbröstet i bitstora kuber, lägg det sedan i en skål med limejuice, avokadoolja, chilipulver, spiskummin, vitlökspulver, paprika, salt och svartpeppar. Blanda väl och marinera i 15 till 30 minuter."},{"title":"Stek kyckling","text":"Värm en stor stekpanna på medelhög värme. Tillsätt den marinerade kycklingen och stek i 8 till 10 minuter, rör om då och då, tills den är brynt och helt genomstekt."},{"title":"Rosta majs","text":"Låt den konserverade majsen rinna av ordentligt och torka den torr med hushållspapper. I samma panna eller en ren varm panna, tillsätt majsen i ett enda lager och låt den ligga orörd i 2 till 3 minuter, rör sedan om och stek ytterligare 2 till 3 minuter tills den fått färg på vissa ställen."},{"title":"Förbered sås","text":"Blanda grekisk yoghurt, limejuice, chilisås, Tajín, vatten, salt och svartpeppar i en skål tills det är slätt."},{"title":"Blanda grönsaker","text":"I en stor skål, tillsätt den rostade majsen, rödlöken, den röda paprikan, koriandern, jalapeños och cotijaosten."},{"title":"Blanda salladen","text":"Häll i såsen och blanda allt tills det är väl täckt."},{"title":"Servera och förvara","text":"Dela upp kycklingen och majssalladen i 4 portioner. Förvara kyld och ät inom 3 till 4 dagar."}],"tips":[{"title":"Seattle","text":"Använd mild chili och ta bort fröna från jalapeños för en mildare smak som passar även de yngsta."},{"title":"Förbered i förväg","text":"Hacka alla grönsaker och koka kycklingen dagen innan för en snabbare middag när tiden är knapp."},{"title":"Variationer","text":"Lägg till svarta bönor eller tärnad avokado för extra textur och smak som kompletterar salladen väl."},{"title":"Serveringsförslag","text":"Servera salladen i tortillabåtar, som fyllning i wraps eller som ett fräscht tillbehör till grillat."}],"image":"/api/images/recipes/mexican-chicken-corn-salad.jpg"}', updated_at = datetime('now') WHERE id = 'mexican-chicken-corn-salad';
UPDATE recipes SET data = '{"id":"hot-honey-chicken-sliders","title":"Kycklingslider med het honung","category":"middag","baseServings":6,"source":"@panaceapalm på Instagram","sourceUrl":"https://www.instagram.com/p/DXcAh2JjYA_/","tags":["kyckling"],"macros":{"kcal":3961,"prot":330,"carb":237,"fat":185},"groups":[{"name":"Kycklingfyllning","ingredients":[{"name":"kycklingbröst","amount":800,"unit":"g"},{"name":"paprika","amount":1,"unit":"msk"},{"name":"lökpulver","amount":1,"unit":"msk"},{"name":"vitlökspulver","amount":1,"unit":"msk"},{"name":"cayennepeppar","amount":1,"unit":"tsk"},{"name":"svartpeppar","amount":2,"unit":"tsk"},{"name":"salt","amount":1,"unit":"msk"},{"name":"rödlök (halv)","amount":0.5,"unit":"st"},{"name":"majs","amount":2,"unit":"msk"},{"name":"lättost 50% cheddar","amount":90,"unit":"g"},{"name":"oregano","amount":2,"unit":"tsk"},{"name":"chilisås","amount":60,"unit":"g"},{"name":"honung","amount":1,"unit":"msk"}]},{"name":"Chilimajonnäs","ingredients":[{"name":"lätt majonnäs","amount":2,"unit":"msk"},{"name":"sriracha","amount":1,"unit":"msk"},{"name":"honung","amount":1,"unit":"tsk"}]},{"name":"Bröd och ost","ingredients":[{"name":"brioche hamburgerbröd (mini)","amount":6,"unit":"st"},{"name":"swiss-ost / leerdamer 50%","amount":100,"unit":"g"},{"name":"mozzarella","amount":250,"unit":"g"},{"name":"skivade pickles","amount":1,"unit":"msk"}]},{"name":"Vitlökssmör","ingredients":[{"name":"lätt smör","amount":1,"unit":"msk"},{"name":"vitlökspasta","amount":0.5,"unit":"tsk"},{"name":"persiljeflakes","amount":1,"unit":"tsk"}]}],"steps":[{"title":"Ugn på","text":"190°C. Tillaga och strimla kyckling, blanda med kryddor, lök, majs, ost, oregano, chilisås och honung."},{"title":"Sriracha mayo","text":"Rör ihop majonnäs, sriracha och honung."},{"title":"Bygg","text":"Mayo på brödbotten. Kycklingfyllning. Swiss-ost och mozzarella över."},{"title":"Grädda","text":"10–12 min tills osten är smält."},{"title":"Vitlökssmör","text":"Pensla på toppen sista 2 min."},{"title":"Servera","text":"Lägg på pickles och servera direkt."}],"tips":[{"title":"Seattle","text":"Skippa cayenne, minska chilisås, mer honung."},{"title":"Förvaring","text":"Folie + mikra 30 sek + airfrya för crispighet."},{"title":"Per slider","text":"560 kcal · 56g protein · 33g kolhydrater · 21g fett."},{"title":"Variationer","text":"Pulled kyckling i bulk. Swiss mot blåmögelost för mer karaktär."}],"image":"/api/images/recipes/hot-honey-chicken-sliders.jpg","badges":["6 sliders","12 min","hög protein"]}', updated_at = datetime('now') WHERE id = 'hot-honey-chicken-sliders';
